package id.unnes.bemfhunnes; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(SecurityException.class) ResponseEntity<?> auth(SecurityException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("message",e.getMessage()));}@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
